#include <stdio.h>
#include <stdlib.h>
#include <limits.h>

unsigned long long secondSmallest(const unsigned long long* arr, size_t len) {
    if (len < 2) {
        return 0;
    }

    unsigned long long p = ULLONG_MAX;
    unsigned long long q = ULLONG_MAX;

    for (size_t i = 0; i < len; i++) {
        unsigned long long val = arr[i];

        if (val < p) {
            q = p;
            p = val;
        } else if (val > p && val < q) {
            q = val;
        }
    }

    return q;
}

int main() {
    {
        unsigned long long arr[] = {5, 3, 1, 4, 2};
        size_t len = sizeof(arr) / sizeof(arr[0]);
        unsigned long long result = secondSmallest(arr, len);
        printf("%llu\n", result);
    }

    {
        unsigned long long arr[] = {100, 200, 300, 400, 500};
        size_t len = sizeof(arr) / sizeof(arr[0]);
        unsigned long long result = secondSmallest(arr, len);
        printf("%llu\n", result);
    }

    {
        unsigned long long arr[] = {42, 42, 42, 7, 42};
        size_t len = sizeof(arr) / sizeof(arr[0]);
        unsigned long long result = secondSmallest(arr, len);
        printf("%llu\n", result);
    }

    {
        unsigned long long arr[] = {0, 0, 1, 0, 2};
        size_t len = sizeof(arr) / sizeof(arr[0]);
        unsigned long long result = secondSmallest(arr, len);
        printf("%llu\n", result);
    }

    {
        unsigned long long arr[] = {ULLONG_MAX, ULLONG_MAX - 1, ULLONG_MAX - 2};
        size_t len = sizeof(arr) / sizeof(arr[0]);
        unsigned long long result = secondSmallest(arr, len);
        printf("%llu\n", result);
    }

    return 0;
}

