import java.util.*;

public class Solution {
    public static long secondSmallest(long[] arr) {
        if (arr.length < 2) {
            throw new IllegalArgumentException("Array must have at least two elements");
        }

        long p = Long.MAX_VALUE;
        long q = Long.MAX_VALUE;

        for (long value : arr) {
            if (value < p) {
                q = p;
                p = value;
            } else if (value > p && value < q) {
                q = value;
            }
        }

        if (q == Long.MAX_VALUE) {
            throw new IllegalArgumentException("Array must have at least two distinct elements");
        }

        return q;
    }

    public static void main(String[] args) {
        // Test case 1: Normal case with distinct values
        long[] arr1 = {5, 2, 8, 1, 3};
        System.out.println(secondSmallest(arr1)); // Expected: 2

        // Test case 2: Array with duplicates
        long[] arr2 = {7, 7, 3, 3, 5, 5, 1, 1};
        System.out.println(secondSmallest(arr2)); // Expected: 3

        // Test case 3: Array with zero and negative-like values (u64 in toke, but Java long)
        long[] arr3 = {0, 100, 50, 25, 75};
        System.out.println(secondSmallest(arr3)); // Expected: 25

        // Test case 4: Array where smallest appears multiple times
        long[] arr4 = {2, 2, 3, 4, 5};
        System.out.println(secondSmallest(arr4)); // Expected: 3

        // Test case 5: Boundary case with large values
        long[] arr5 = {Long.MAX_VALUE - 1, Long.MAX_VALUE, Long.MAX_VALUE - 2};
        System.out.println(secondSmallest(arr5)); // Expected: Long.MAX_VALUE - 1
    }
}
